"""Synthetic human-review examples, never learner-visible answers or runtime inputs."""
from pathlib import Path
import json,copy
ROOT=Path(__file__).resolve().parents[1];OUT=ROOT/'prototype-specs'
if (ROOT/'governance/TRACK_A_FREEZE_AUTHORITY.json').exists():
 raise SystemExit('Track A is frozen; reviewed proposal artifacts are preserved.')
def row(state,links,gaps=[],priority=None):return dict(state=state,links=[dict(artifact_id=i,version=v,role=r) for i,v,r in links],gap_markers=gaps,gap_priority=priority)
initial={
 'TA-K01':row('sufficient',[('TA-E01',1,'supports'),('TA-E02',1,'supports')],['access_not_tested'],'during_supervised_step'),
 'TA-K02':row('sufficient',[('TA-E02',1,'supports'),('TA-E03',1,'limits_or_contradicts')],['evidence_scope_limited'],'before_real_use'),
 'TA-K03':row('conflicting',[('TA-E01',1,'supports'),('TA-E03',1,'limits_or_contradicts'),('TA-E04',1,'limits_or_contradicts')],['claim_conflicts_with_record','receipt_unverified'],'before_next_step')}
current=copy.deepcopy(initial)
for r in current.values():
 for link in r['links']:
  if link['artifact_id']=='TA-E03':link['version']=2
current['TA-K02']['links']=[dict(artifact_id='TA-E02',version=1,role='supports')]
current['TA-K03']=row('sufficient',[('TA-E03',2,'supports'),('TA-E04',1,'limits_or_contradicts')],['receipt_unverified'],'before_real_use')
def record(version,mappings,route,reason,next):return dict(bundle_version=version,mappings=copy.deepcopy(mappings),route=route,rationale=reason,next_step_note=next)
first=record(1,initial,'revise','The rehearsal shows a specific influence on timing, but the self-review overclaims receipt and public approval. Correct those claims before the next supervised step.','Ask the learner to distinguish preparation from receipt and name the planning team’s authority; reconsider the corrected account with the tutor.')
examples=[dict(id='P01',purpose='Revise then proceed only to supervised rehearsal, with unresolved real-use checks',initial=first,current=record(2,current,'proceed','The clarification now respects authority and distinguishes preparation from receipt. Together with the rehearsal, this supports another supervised practice conversation, not unsupervised work or verified public response.','The tutor should test accessible explanation and understanding in the next rehearsal; verify a safe response route before any real use.'),disposition='amend_recommendation',unresolved=['Disability access not rehearsed','No real delivery or receipt evidence']),
 dict(id='P02',purpose='Retain revise after clarification; credible not-yet without forced prose',initial=record(1,initial,'revise','The bundle does not yet demonstrate accessible account-back. A clear plan and a timing change are useful, but supervised evidence of explaining and checking understanding is still needed.','Ask the tutor to observe an accessible account-back rehearsal and review the learner’s response before judging readiness again.'),current=record(2,{**current,'TA-K03':row('insufficient',[('TA-E03',2,'supports'),('TA-E04',1,'limits_or_contradicts')],['receipt_unverified'],'before_next_step')},'revise','The bundle does not yet demonstrate accessible account-back. A clear plan and a timing change are useful, but supervised evidence of explaining and checking understanding is still needed.','Ask the tutor to observe an accessible account-back rehearsal and review the learner’s response before judging readiness again.'),disposition='retain_recommendation',unresolved=['Correction is intention, not observed account-back']),
 dict(id='P03',purpose='Seek tutor review without pretending public authorization exists',initial=record(1,initial,'seek_review','The learner’s approval and receipt claims conflict with the role check. I can flag that boundary, but a tutor should review readiness for the supervised step.','Send the conflicting criterion and source versions to the tutor in a real review process; here, request the exercise clarification and retain the record.'),current=record(2,current,'seek_review','The clarification resolves the stated authority confusion, but I want tutor review of the planned understanding check before recommending the supervised step. It does not establish actual receipt.','Ask the tutor to review the account-back plan; the learner can prepare a fictional spoken summary while awaiting review.'),disposition='retain_recommendation',unresolved=['Tutor review not actually sent or received']),
 dict(id='P04',purpose='Defer with precise missing evidence and reconsideration trigger',initial=record(1,{**initial,'TA-K03':row('missing',[('TA-E04',1,'limits_or_contradicts')],['receipt_unverified'],'before_next_step')},'defer','I need evidence of how the learner explains a response and checks understanding before recommending this next step. The current record documents preparation rather than that performance.','Arrange a short supervised demonstration with the tutor, then reconsider this criterion; retain the existing participation evidence.'),current=record(2,{**current,'TA-K03':row('insufficient',[('TA-E03',2,'supports'),('TA-E04',1,'limits_or_contradicts')],['receipt_unverified'],'before_next_step')},'defer','The corrected intention is relevant but does not demonstrate the explanation or understanding check. I would defer my recommendation until a short supervised demonstration is available.','Ask the tutor for a bounded demonstration and re-review its observation alongside this clarification.'),disposition='retain_recommendation',unresolved=['Criterion evidence still insufficient for this reviewer’s recommendation'])]
negative=[
 ('N01','Artifact-count assessment','Four documents are present, so every criterion is sufficient.','H01,H03,H10','Reject as semantic evidence: counts do not prove capability.'),
 ('N02','Receipt and authority confusion','Awra approved the plan and a drafted message proves everyone received a response.','H02,H04,H05','Reject: directly overclaims what the supplied record establishes.'),
 ('N03','Suppressed contradiction','Remove E03 and its conflicting claim from the first record so the plan looks ready.','H02,H07','Reject: preserve historical contradictions and exact source versions.'),
 ('N04','Stale approval','Keep the old acknowledged assessment active after the source version changes.','H07,H10','Reject: current assessment invalidates, even if the chosen route remains the same.'),
 ('N05','Indefinite defer','Wait until everything is perfect.','H06,H08,H09','Reject: lacks a proportionate evidence request, owner and reconsideration trigger.'),
 ('N06','Word/keyword pseudo-grading','The answer has enough words and includes rights-holder, so mark the reviewer competent.','H03,H09,H10','Reject: structural bounds and vocabulary cannot grant competence.'),
 ('N07','Forced proceed','Revise and seek review are wrong because Continue requires proceeding.','H05,H08,H10','Reject: practice completion is independent of readiness route.'),
 ('N08','False external assessor','The app says a qualified tutor approved this work although nobody reviewed it.','H05,H10','Reject: deterministic guidance is not independent assessment.')]
d=dict(designation='SYNTHETIC SEMANTIC-REVIEW EVIDENCE ONLY — not model answers, not real plans, not runtime inputs',human_judgment='PENDING_ARCHITECTURAL_REVIEW',case_contract='TRACK_A_AUTHORING_CONTENT_STATE_CONTRACT_v0.1.json',positive_examples=examples,negative_counterexamples=[dict(id=i,title=t,claim=c,dimensions=h,expected_human_critique=e) for i,t,c,h,e in negative])
(OUT/'TRACK_A_SEMANTIC_REVIEW_FIXTURES_v0.1.json').write_text(json.dumps(d,indent=2,ensure_ascii=False)+'\n',encoding='utf-8')
print('Four synthetic review trajectories and eight negative counterexamples; no semantic pass claimed.')
